import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv3d_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int input_depth, int input_height, int input_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups,
    int output_depth, int output_height, int output_width
) {
    int total_elements = batch_size * out_channels * output_depth * output_height * output_width;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int b = idx / (out_channels * output_depth * output_height * output_width);
    int remainder = idx % (out_channels * output_depth * output_height * output_width);
    int oc = remainder / (output_depth * output_height * output_width);
    remainder %= (output_depth * output_height * output_width);
    int od = remainder / (output_height * output_width);
    remainder %= (output_height * output_width);
    int oh = remainder / output_width;
    int ow = remainder % output_width;

    int group_size = out_channels / groups;
    int g = oc / group_size;
    int in_channels_per_group = in_channels / groups;
    int in_group_start = g * in_channels_per_group;

    float sum = 0.0f;

    for (int kd = 0; kd < kernel_d; ++kd) {
        int input_d = od * stride_d - padding_d + kd * dilation_d;
        if (input_d < 0 || input_d >= input_depth) continue;
        for (int kh = 0; kh < kernel_h; ++kh) {
            int input_h = oh * stride_h - padding_h + kh * dilation_h;
            if (input_h < 0 || input_h >= input_height) continue;
            for (int kw = 0; kw < kernel_w; ++kw) {
                int input_w = ow * stride_w - padding_w + kw * dilation_w;
                if (input_w < 0 || input_w >= input_width) continue;
                for (int ic = 0; ic < in_channels_per_group; ++ic) {
                    int input_c = in_group_start + ic;
                    int input_idx = b * in_channels * input_depth * input_height * input_width +
                                    input_c * input_depth * input_height * input_width +
                                    input_d * input_height * input_width +
                                    input_h * input_width +
                                    input_w;
                    int weight_idx = oc * (in_channels_per_group * kernel_d * kernel_h * kernel_w) +
                                     ic * (kernel_d * kernel_h * kernel_w) +
                                     kd * (kernel_h * kernel_w) +
                                     kh * kernel_w +
                                     kw;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias) sum += bias[oc];

    int output_idx = b * out_channels * output_depth * output_height * output_width +
                     oc * output_depth * output_height * output_width +
                     od * output_height * output_width +
                     oh * output_width +
                     ow;
    output[output_idx] = sum;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups
) {
    TORCH_CHECK(input.dim() == 5, "Input must be 5D");
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);

    TORCH_CHECK(weight.dim() == 5, "Weight must be 5D");
    int out_channels = weight.size(0);

    int output_depth = (input_depth + 2 * padding_d - dilation_d * (kernel_d - 1) - 1) / stride_d + 1;
    int output_height = (input_height + 2 * padding_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    int output_width = (input_width + 2 * padding_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({batch_size, out_channels, output_depth, output_height, output_width}, input.options());

    int total_elements = batch_size * out_channels * output_depth * output_height * output_width;
    const int threads_per_block = 256;
    int num_blocks = (total_elements + threads_per_block - 1) / threads_per_block;

    conv3d_forward_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        input_depth, input_height, input_width,
        kernel_d, kernel_h, kernel_w,
        stride_d, stride_h, stride_w,
        padding_d, padding_h, padding_w,
        dilation_d, dilation_h, dilation_w,
        groups,
        output_depth, output_height, output_width
    );

    return output;
}
"""

conv3d_cpp_source = """
torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups
);
"""

conv3d_extension = load_inline(
    name='conv3d_extension',
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_cuda_source,
    functions=['conv3d_forward_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), dilation: tuple = (1, 1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            out_channels, in_channels // groups, *kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_tensor = self.bias if self.bias is not None else torch.Tensor()
        return conv3d_extension.conv3d_forward_cuda(
            x,
            self.weight,
            bias_tensor,
            self.kernel_size[0], self.kernel_size[1], self.kernel_size[2],
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.dilation[0], self.dilation[1], self.dilation[2],
            self.groups
        )
